    row_mask = pid < N

    acc_ap = tl.zeros([BLOCK_M], dtype=acc_dtype)
    acc_an = tl.zeros([BLOCK_M], dtype=acc_dtype)
    acc_pn = tl.zeros([BLOCK_M], dtype=acc_dtype)

    for start in range(0, D, BLOCK_D):
        cols = start + tl.arange(0, BLOCK_D)[None, :]
        col_mask = cols < D
